{
  "title":"Syllabus",
  "content":" Course Meeting Times Lectures: 2 sessions/week, 1.5 hours/session\nPrerequisites 18.02 Multivariable Calculus\nDescription This course gives an introduction to analysis, and the goal is twofold: To learn how to prove mathematical theorems in analysis and how to write proofs. To prove theorems in calculus in a rigorous way. The course will start with real numbers, limits, convergence, series and continuity. We will continue on with metric spaces, differentiation and Riemann integrals. After that, we will move on to differential equations. Textbooks Main Textbook Brian S. Thomson, Judith B. Bruckner, and Andrew M. Bruckner. 2008. Elementary Real Analysis. 2nd ed. ISBN: 9781434843678\nA screen-optimized PDF version of the textbook is available. A print-optimized PDF version of the textbook is available. Other Textbook Rudin, Walter. 1976. Principles of Mathematical Analysis (International Series in Pure and Applied Mathematics). 3rd ed. McGraw-Hill. ISBN: 9780070542358 The latest edition is the 1976 third edition. It’s not available to purchase as an ebook, but it has been digitized by the Internet Archive. You can access the book by creating a free personal Internet Archive account. You can then log in and borrow the book (for one hour at a time, looks like). Requirements Problem Sets The problem sets will be assigned weekly. They should be submitted on Tuesdays by 4 PM online. The graded assignments will be returned the following Tuesday. The lowest problem set grade will be dropped. We are planning on having ten sets of homework. Exams There will be one in-class midterm. We will have an honesty pledge on the first page to help with academic integrity. You may not use a computer or a textbook for the midterm or final, but you are allowed to bring one page of notes. The final exam will be three hours. Collaboration Collaboration on homework is very much encouraged. However, no collaboration on the midterm or final is allowed. Also, even though collaboration on homework is encouraged, everyone should hand in their own personal sets of homework. Grading The course grade will be determined as follows: Problem sets (50%) 1.5-hour midterm exam (20%) 3-hour final exam (30%) "}

$ powershell -NoProfile -Command "
$src = 'C:\Users\27063\Desktop\工具箱\输出文件\18.100B-spring-2025'
$res = $src + '\static_resources'
$dst = 'D:\b站视频\解析视频\数学分析\06-字幕文件'
$titles = @(
    'Introduction to Real Numbers','Introduction to Real Numbers (cont.)','How to Write a Proof; Archimedean Property','Sequences; Convergence','Monotone Convergence Theorem','Cauchy Convergence Theorem','Bolzano-Weierstrass Theorem; Cauchy Sequences; Series','Convergence Tests for Series; Power Series','Limsup and Liminf; Power Series; Continuous Functions; Exponential Function','Continuous Functions; Exponential Function (cont.)','Extreme and Intermediate Value Theorem; Metric Spaces','Convergence in Metric Spaces; Operations on Sets','Open and Closed Sets; Coverings; Compactness','Sequential Compactness; Bolzano-Weierstrass Theorem in a Metric Space','Derivatives; Laws for Differentiation','Rolle Theorem; Mean Theorem; LHopital Rule; Taylor Expansion','Taylor Polynomials; Remainder Term; Riemann Integrals','Integrable Functions','Fundamental Theorem of Calculus','Pointwise Convergence; Uniform Convergence','Integrals and Derivatives under Uniform Convergence','Differentiating and Integrating Power Series; ODEs','Existence and Uniqueness for ODEs; Picard-Lindelof Theorem'
)
# Build mapping: transcript basename -> filename prefix
$map = @{}
for ($i = 1; $i -le 23; $i++) {
    $n = $i.ToString('D2')
    $jp = $src + '\resources\ocw_18100b-lec' + $n + '_mp4\data.json'
    if (Test-Path $jp) {
        $j = Get-Content $jp -Raw | ConvertFrom-Json
        if ($j.transcript_file) {
            $tb = [System.IO.Path]::GetFileNameWithoutExtension($j.transcript_file)
            $safe = $titles[$i-1] -replace '[<>:\"/\\|?*]','-'
            $map[$tb] = 'V' + $n + ' - ' + $safe
        }
    }
}
# Midterm
$jp = $src + '\resources\ocw_18100b-midterm-review-2025mar18_mp4\data.json'
if (Test-Path $jp) { $j = Get-Content $jp -Raw | ConvertFrom-Json; if($j.transcript_file){$tb=[System.IO.Path]::GetFileNameWithoutExtension($j.transcript_file);$map[$tb]='Midterm-Review'} }
# Final
$jp = $src + '\resources\ocw_18100b-final-exam-review-2025may13_mp4\data.json'
if (Test-Path $jp) { $j = Get-Content $jp -Raw | ConvertFrom-Json; if($j.transcript_file){$tb=[System.IO.Path]::GetFileNameWithoutExtension($j.transcript_file);$map[$tb]='Final-Exam-Review'} }

# Copy transcript files
$count = 0
Get-ChildItem ($res + '\*_transcript.pdf'), ($res + '\*_transcript.webvtt') | ForEach-Object {
    $base = $_.BaseName -replace '_transcript$', ''
    $ext = $_.Extension
    if ($map.ContainsKey($base)) {
        $newName = $map[$base] + '_transcript' + $ext
        Copy-Item $_.FullName ($dst + '\' + $newName) -Force
        $count++
    }
}
Write-Output ('Copied ' + $count + ' subtitle files')
"
[exit 0]
Copied 0 subtitle files

